class CustomerMapper {
public:
    explicit CustomerMapper(sqlite3* db) : db_{db} {}

    std::optional<Customer> find(std::int64_t id) {
        Stmt st{db_, "SELECT id, name FROM customers WHERE id = ?"};  // RAII wrapper
        st.bind(1, id);
        if (st.step() != SQLITE_ROW) return std::nullopt;
        return Customer{st.column_int64(0), st.column_text(1)};       // plain domain type
    }
private:
    sqlite3* db_;
};

